import argparse
import json
from fractions import Fraction
import sys


def read_rectangles(lines):
    rectangles = []
    for number, raw in enumerate(lines, 1):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        values = [Fraction(value) for value in line.split()]
        if len(values) != 4:
            raise ValueError(f"line {number}: expected four coordinates")
        rectangles.append(tuple(values))
    return rectangles


def union_area(rectangles):
    # Extract all boundary points and sort them.
    points = set()
    for x1, y1, x2, y2 in rectangles:
        points.update([x1, x2])
        points.update([y1, y2])
    points = sorted(points)

    # Create a grid of cells from the boundary points.
    cell_widths = [points[i+1] - points[i] for i in range(len(points) - 1)]
    total_area = sum(cell * (cell_widths[i + 1] if i < len(cell_widths) - 1 else 0)
                     for i, cell in enumerate(points[:-1]))

    # Check each cell against all rectangles to determine coverage.
    covered_cells = set()
    for x1, y1, x2, y2 in rectangles:
        for x in range(points.index(x1), points.index(x2) + 1):
            for y in range(points.index(y1), points.index(y2) + 1):
                if (x, y) not in covered_cells and all(
                        p[0] <= x < p[2] and p[1] <= y < p[3]
                        for p in rectangles
                ):
                    covered_cells.add((x, y))

    # Calculate the area of covered cells.
    covered_area = sum(cell_widths[i] * (points[i + 1] - points[i])
                       for i in range(len(points) - 1)
                       if any(p == (i, j) for p in covered_cells))

    return total_area - covered_area


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("--input")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args(argv)
    stream = open(args.input) if args.input else sys.stdin
    try:
        area = union_area(read_rectangles(stream))
    finally:
        if args.input:
            stream.close()
    text = str(int(area.numerator) // int(area.denominator)) if area.denominator == 1 else f'{area.numerator}/{area.denominator}'
    print(json.dumps({"area": text}) if args.json else text)


